<?php declare(strict_types=1); namespace App\Domains\Patient\Resources; use Illuminate\Http\Request; use Illuminate\Http\Resources\Json\JsonResource;
final class PatientResource extends JsonResource { public function toArray(Request $r): array { return ['id'=>$this->id,'patient_code'=>$this->patient_code,'full_name'=>$this->full_name,'birth_date'=>$this->birth_date?->toDateString(),'gender'=>$this->gender,'blood_type'=>$this->blood_type,'religion'=>$this->religion,'marital_status'=>$this->marital_status,'nationality_id'=>$this->nationality_id,'patient_type_id'=>$this->patient_type_id,'patient_type'=>$this->patientType?->name,'organization_id'=>$this->organization_id,'branch_id'=>$this->branch_id,'phone'=>$this->phone,'email'=>$this->email,'address'=>$this->address,'district_id'=>$this->district_id,'village_id'=>$this->village_id,'is_active'=>$this->is_active,'created_at'=>$this->created_at?->toISOString(),'updated_at'=>$this->updated_at?->toISOString()]; } }
